#include <vector>
#include <unordered_map>

class Solution {
public:
    long long countShadowPairs(std::vector<int>& nums) {
        std::unordered_map<int, int> freq;
        long long pairs = 0;
        for (int i = 0; i < (int)nums.size(); ++i) {
            int key = nums[i] - i;
            pairs += freq[key];
            freq[key]++;
        }
        return pairs;
    }
};

import java.util.*;

class Solution {
    public long countShadowPairs(int[] nums) {
        Map<Integer, Integer> freq = new HashMap<>();
        long pairs = 0;
        for (int i = 0; i < nums.length; i++) {
            int key = nums[i] - i;
            pairs += freq.getOrDefault(key, 0);
            freq.put(key, freq.getOrDefault(key, 0) + 1);
        }
        return pairs;
    }
}

